/* ==========================================================================
   8. 悬浮字幕翻译（点气泡秒收起 + 动态下推完美自适应版）
   ========================================================================== */

/* 隐藏原生文本 */
.msg-translation-content {
  display: none !important;
}

/* 关键：在透明内容栈上垫出底部空间，把下一个气泡硬顶开，且不带底色 */
.msg-content-stack:has(.msg-translation-btn) {
  padding-bottom: 21px !important;
}

/* 展开字幕后把垫的高度收掉，避免冗余空隙 */
.msg-content-stack:has(.msg-translation-detached-content:not(:empty)) {
  padding-bottom: 0px !important;
}

/* 翻译按钮容器：绝对定位悬浮在刚刚垫出来的透明空白里 */
.msg-translation-wrapper {
  position: absolute !important;
  bottom: -26px !important;
  left: -7.5px !important;
  right: auto !important;
  padding: 0 !important;
  display: flex !important;
  pointer-events: none !important;
  white-space: nowrap !important; /* 强制不换行 */
}

/* 纯白文字 + 黑色阴影 */
.msg-translation-btn {
  font-size: 0 !important;
  display: inline-flex !important;
  align-items: center !important;
  opacity: 0.9 !important;
  cursor: pointer !important;
  padding: 0 !important;
  pointer-events: auto !important;
}
.msg-translation-btn svg { display: none !important; }
.msg-translation-btn::after {
  content: "1个翻译 ›" !important;
  font-size: 11px !important;
  font-weight: 600 !important;
  color: #000000 !important;
  letter-spacing: 0.5px !important;
  text-shadow: 0 0.5px 2px rgba(255, 255, 255, 0.6) !important;
}

/* 展开时：把 wrapper 和 btn 变成全透明绝对定位遮罩，不占任何高度，直接盖满整个气泡 */
.msg-bubble-wrapper:has(.msg-translation-detached-content:not(:empty)) .msg-translation-wrapper {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  z-index: 20 !important;
  pointer-events: auto !important;
  cursor: pointer !important;
}
.msg-bubble-wrapper:has(.msg-translation-detached-content:not(:empty)) .msg-translation-btn {
  position: absolute !important;
  inset: 0 !important;
  width: 100% !important;
  height: 100% !important;
  opacity: 0 !important;
  z-index: 21 !important;
  cursor: pointer !important;
  pointer-events: auto !important;
}
.msg-bubble-wrapper:has(.msg-translation-detached-content:not(:empty)) .msg-translation-btn::after {
  display: none !important;
}

/* 独立外部容器：骑住底边，长短自适应，自动顶开后续一切内容 */
.msg-translation-detached {
  display: block !important;
  width: 100% !important;
  max-width: 100% !important;
  margin-top: -8px !important;
  margin-bottom: 8px !important;
  box-sizing: border-box !important;
  clear: both !important;
  position: relative !important;
  z-index: 10 !important;
  pointer-events: none !important;
}
.msg-translation-detached-them {
  align-self: center !important;
}

/* 悬浮字幕文字：八向黑描边、line-height:1 完全保留 */
.msg-translation-detached-content {
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  border-radius: 0 !important;
  padding: 0 !important;
  margin: 0 auto !important;
  transform: translateX(-4px) !important;
  width: max-content !important;
  min-width: 60px !important;
  max-width: 84% !important;
  word-break: break-word !important;
  white-space: normal !important;
  text-align: center !important;
  color: #ffffff !important;
  font-weight: 600 !important;
  font-size: 13.5px !important;
  line-height: 1 !important;
  pointer-events: none !important;
  box-sizing: border-box !important;
  text-shadow:
    0.8px  0.0px 0 #000,
   -0.8px  0.0px 0 #000,
    0.0px  0.8px 0 #000,
    0.0px -0.8px 0 #000,
    0.6px  0.6px 0 #000,
   -0.6px -0.6px 0 #000,
    0.6px -0.6px 0 #000,
   -0.6px  0.6px 0 #000,
    0px 1px 2px rgba(0, 0, 0, 0.6) !important;
}

/* 清除冗余 padding */
.msg-bubble-wrapper:has(.msg-translation-content:not(:empty)),
.msg-bubble-wrapper:has(.msg-translation-detached-content:not(:empty)) {
  padding-bottom: 0px !important;
}
/* =============================
   针对带小尾巴气泡的专属微调（避开尾巴 + 字幕精准贴边）   
=============================*/

/* 1. 未展开时：把带小尾巴的“1条翻译”再往下挪一点，避开尾巴尖 */
.msg-bubble-wrapper.is-last .msg-translation-wrapper,
.msg-bubble-wrapper.is-single .msg-translation-wrapper {
  left: 2px !important;
  bottom: -26px !important; /* 如果觉得还碰尾巴，可以改成 -30px 或 -32px */
}

/* 配合往下挪的按钮，把带尾巴的透明占位也稍微加大一点防撞车 */
.msg-bubble-wrapper.is-last .msg-content-stack:has(.msg-translation-btn),
.msg-bubble-wrapper.is-single .msg-content-stack:has(.msg-translation-btn) {
  padding-bottom: 30px !important;
}

