}

/* ✅ 气泡去除包裹效果（核心：精确过滤隐藏引用块里的图片，恢复表情包去气泡功能） */
:is(.bubble-me-custom, .bubble-them-custom):has(:is( .msg-transfer-card, .msg-redpacket-card, .msg-videocall-card, .msg-loc-card, .msg-sim-card, .msg-file-card, [class*="file-card"], .gift-ig-container, .msg-image-wrapper, .msg-image-card, img:not(.msg-reply-block img, .msg-reply-block-detached img))) {
