/* ========================================================
   💌 「未读/已读」纯文字美化（脱标浮动，完全不撑大消息间距）
   ======================================================== */
/* 1. 确保气泡堆栈外层为相对定位，作为锚点 */
.msg-content-stack {
    position: relative !important;
}

/* 2. 状态文字脱标：绝对定位，悬浮在气泡下方，占用高度归 0 */
.msg-status-custom {
    position: absolute !important;
    top: 100% !important;                  /* 紧贴气泡底边下方 */
    right: 4px !important;                 /* 右对齐 */
    height: 0 !important;                  /* 核心：高为0，坚决不占物理位置 */
    margin: 0 !important;
    padding: 0 !important;
    font-size: 0 !important;
    color: transparent !important;
    pointer-events: none !important;
    white-space: nowrap !important;
}

/* 3. 未读文字渲染 (利用相对偏移让文字自然下沉展示) */
.msg-status-custom::after {
    content: "An anonymous letter" !important;
    display: block !important;
    position: relative !important;
    top: 2px !important;                   /* 距离气泡下边缘 2px 微调 */
    font-size: 11px !important;
    font-style: italic !important;
    font-family: -apple-system, BlinkMacSystemFont, "Georgia", "Times New Roman", serif !important;
    color: #999999 !important;
    letter-spacing: 0.3px !important;
    opacity: 0.85 !important;
    line-height: 1 !important;
    transition: all 0.3s ease !important;
}

/* 4. 已读文字渲染 */
.msg-status-custom.is-read::after {
    content: "@抵达春日" !important;
    font-style: normal !important;
    font-weight: 500 !important;
    font-family: -apple-system, BlinkMacSystemFont, "PingFang SC", "Segoe UI", sans-serif !important;
    color: #555555 !important;
    letter-spacing: 0.5px !important;
    opacity: 0.95 !important;
}

/* 5. 连发控制：非末条直接彻底隐藏容器 */
.msg-bubble-wrapper.is-first .msg-status-custom,
.msg-bubble-wrapper.is-mid .msg-status-custom {
    display: none !important;
}

/* 6. 只给显示了文字的「末尾单条」微微预留文字展示距离（微信原生视觉） */
.msg-bubble-wrapper.is-last:has(.msg-status-custom),
.msg-bubble-wrapper.is-single:has(.msg-status-custom) {
    margin-bottom: 25px !important;        /* 👈 仅在有文字展示的末尾条垫高 10px 放小字，防止撞到对方下一条消息 */
}

@media (prefers-color-scheme: dark) {
    .msg-status-custom::after {
        color: #7C7C80 !important;
    }
    .msg-status-custom.is-read::after {
        color: #AEAEB2 !important;
    }
}

