.msg-reaction-badge {
  position: absolute !important;
  bottom: -14px !important; /* 👈 核心下移：彻底脱离气泡内部文字区域，不挡字！ */
  background: #ffffff !important;
  border: none !important; /* 👈 去除玻璃边框 */
